package ec.dmt.admin.school;
import ec.dmt.admin.user.*; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/inspector-courses") public class InspectorCourseController { private final InspectorCourseRepository repo; private final AppUserRepository users; private final CourseRepository courses; public InspectorCourseController(InspectorCourseRepository r,AppUserRepository u,CourseRepository c){repo=r;users=u;courses=c;}
 @GetMapping("/mine") public List<View> mine(org.springframework.security.core.Authentication a){return repo.findByUserUsername(a.getName()).stream().map(x->new View(x.getId(),x.getCourse().getId(),x.getCourse().getName(),x.getCourse().getCourseOrder())).toList();}
 @PostMapping("/{userId}/range") @Transactional public List<View> assignRange(@PathVariable Long userId,@RequestBody Range range){AppUser u=users.findById(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Usuario no encontrado"));Course from=courses.findById(range.fromCourseId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Curso inicial no encontrado"));Course to=courses.findById(range.toCourseId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Curso final no encontrado"));if(from.getCourseOrder()>to.getCourseOrder())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El rango no es válido");List<View> result=new ArrayList<>();for(Course c:courses.findAll().stream().filter(x->x.getCourseOrder()>=from.getCourseOrder()&&x.getCourseOrder()<=to.getCourseOrder()).toList()){if(!repo.existsByUserIdAndCourseId(userId,c.getId())){InspectorCourse x=repo.save(new InspectorCourse(u,c));result.add(new View(x.getId(),c.getId(),c.getName(),c.getCourseOrder()));}}return result;}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable Long id){repo.deleteById(id);} public record Range(Long fromCourseId,Long toCourseId){} public record View(Long id,Long courseId,String courseName,int order){} }
